points = 0
actions = 0
while True:
    command = input("Action: ")
    if command == "quit":
        break
    if command == "add":
        points += 2
    elif command == "undo":
        points -= 2
    else:
        continue
    actions += 1
print(f"Points: {points}")
print(f"Actions: {actions}")
